alvo as (
  select p.id, p.restaurant_id, p.name, p.price, g.glovo::numeric glovo,
         round(g.glovo::numeric/1.15,2) b
    from public.products p
    join g on g.loja=p.restaurant_id
          and lower(regexp_replace(trim(g.nome),'\s+',' ','g'))=lower(regexp_replace(trim(p.name),'\s+',' ','g'))
   where round(p.price*1.15,2) < g.glovo
),
nova as (
  select *, case when round(b*1.15,2) < glovo then b+0.01
                 when round(b*1.15,2) > glovo then b-0.01 else b end nb
    from alvo
),
bk as (
  insert into public.bkp_precos_glovo_20261023 (id,restaurant_id,name,price,backup_at)
  select id,restaurant_id,name,price,now() from nova returning 1
)
update public.products p set price = n.nb
  from nova n
 where p.id=n.id and n.nb > p.price;
